insert into public.course_content_draft (course_id, what_you_build, what_you_learn, session, starter_code, test_it_out, troubleshooting, resources, tier, change_note)
values (
  10,
  $wyb$A scraper that checks a competitor's product page, compares it against the last saved snapshot, and uses AI to turn any price or lineup change into a plain-English summary you can drop straight into an email alert -- built from real, tested Python you can read, run and extend, with the AI called through your AI Builder credits instead of a subscription of your own.$wyb$,
  $wyl$[
  "Extract structured data from a web page with CSS selectors and BeautifulSoup",
  "Write pure, testable functions by separating the network call from the parsing logic",
  "Detect and classify changes between two snapshots: price changed, product added, product removed",
  "Turn raw structured changes into an AI-written plain-English summary",
  "Parse an AI reply safely using bracket markers instead of fragile JSON",
  "Handle a malformed or missing AI reply without losing the underlying alert",
  "Schedule a Python script to run unattended, and know why it can silently stop"
]$wyl$::jsonb,
  $sess${
  "model": "Claude Haiku 4.5 (via your AI Builder credits)",
  "totalTime": "150 min",
  "buildCount": 5,
  "whatYouNeed": [
    "Your AI Builder key (Credits page on your dashboard)",
    "Python 3.10+ installed",
    "Basic HTML/CSS selector knowledge",
    "1-3 competitor product pages you want to track, plus a few minutes with browser dev tools to find their price elements"
  ],
  "outcomes": [
    "Extract a product's name and price from any page using CSS selectors",
    "Detect exactly what changed between two runs: price changed, product added, or product removed",
    "Get an AI-written plain-English summary of a change instead of a wall of JSON",
    "Know how the code recovers when the AI reply doesn't come back in the format you asked for",
    "Have a script that can run unattended on a schedule"
  ],
  "builds": [
    {
      "number": 1,
      "title": "Scrape one product page",
      "time": "35 min",
      "description": "Before you can detect a change, you need code that reliably reads a product's name and price off a page -- and a way to test that logic without depending on a live website's HTML staying still for months.",
      "steps": [
        {
          "instruction": "Create `scraper.py` with this code:",
          "prompt": "\"\"\"\nStep 1 of the Price & Competitor Monitor Agent.\n\nThis file has one job: given a product page's URL and two CSS selectors,\npull out the product name and price. Everything else on the page --\nnavigation, footer, \"customers also bought\" -- is noise we ignore.\n\"\"\"\n\nimport requests\nfrom bs4 import BeautifulSoup\n\n# Websites often block programs that don't look like a real browser.\n# Telling them we're a normal browser avoids most of that.\nBROWSER_HEADER = {\"User-Agent\": \"Mozilla/5.0\"}\n\n\ndef scrape_product(url, name_selector, price_selector):\n    \"\"\"\n    Downloads a page and pulls out the product name + price using the\n    CSS selectors you give it.\n\n        product = scrape_product(\n            \"https://example.com/widget\",\n            name_selector=\".product-title\",\n            price_selector=\".price\",\n        )\n        print(product)  # {\"name\": \"Widget Pro\", \"price\": \"$49.00\"}\n\n    Raises a clear error if the page can't be fetched, or if a selector\n    doesn't match anything on the page (which almost always means the\n    site's HTML changed, or you copied the wrong selector).\n    \"\"\"\n    try:\n        page = requests.get(url, headers=BROWSER_HEADER, timeout=15)\n        page.raise_for_status()\n    except requests.RequestException as problem:\n        raise ValueError(\n            f\"Could not open {url}.\\n\"\n            f\"Check the address is correct and that the page opens in your browser.\\n\"\n            f\"(Details: {problem})\"\n        )\n\n    return parse_product_html(page.text, name_selector, price_selector)\n\n\ndef parse_product_html(html, name_selector, price_selector):\n    \"\"\"\n    The actual extraction logic, kept separate from the network call above.\n\n    Splitting it out like this lets us test the parsing against a fixed\n    piece of HTML we control (see the self-test at the bottom) instead\n    of depending on a live website's markup staying the same forever. A\n    real competitor site can change its CSS class names at any time with\n    zero warning; a hand-written fixture string never breaks by surprise\n    months from now for a reason unrelated to your code.\n    \"\"\"\n    soup = BeautifulSoup(html, \"html.parser\")\n\n    name_tag = soup.select_one(name_selector)\n    price_tag = soup.select_one(price_selector)\n\n    if name_tag is None or price_tag is None:\n        missing = []\n        if name_tag is None:\n            missing.append(f\"name selector '{name_selector}'\")\n        if price_tag is None:\n            missing.append(f\"price selector '{price_selector}'\")\n        raise ValueError(\n            \"Couldn't find \" + \" or \".join(missing) + \" on that page.\\n\"\n            \"The site's HTML probably changed since you picked the selector, \"\n            \"or you copied the wrong one. Open the page in your browser, \"\n            \"right-click the price, choose Inspect, and copy the new selector.\"\n        )\n\n    return {\n        \"name\": name_tag.get_text(strip=True),\n        \"price\": price_tag.get_text(strip=True),\n    }\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the parsing logic works:\n    #     python scraper.py\n    #\n    # This is a hand-written fixture, not a live page. A real competitor\n    # site can redesign its pricing page at any time with no warning --\n    # if this test depended on requests.get() hitting a real URL, it\n    # could start failing months from now for a reason that has nothing\n    # to do with your code. Testing against a string we control means\n    # this test only ever fails when parse_product_html() itself breaks.\n    fake_page = \"\"\"\n    <html><body>\n      <nav>Home | Pricing | Contact</nav>\n      <div class=\"product-card\">\n        <h2 class=\"product-title\">Widget Pro</h2>\n        <span class=\"price\">$49.00</span>\n      </div>\n      <footer>(c) 2026 Example Store</footer>\n    </body></html>\n    \"\"\"\n\n    result = parse_product_html(\n        fake_page, name_selector=\".product-title\", price_selector=\".price\"\n    )\n    print(\"Parsed:\", result)\n    assert result == {\"name\": \"Widget Pro\", \"price\": \"$49.00\"}, \"Parsing broke!\"\n\n    # A selector that matches nothing should raise a clear error, not\n    # crash with an AttributeError three lines later on a None value.\n    try:\n        parse_product_html(fake_page, name_selector=\".no-such-class\", price_selector=\".price\")\n        raise AssertionError(\"Expected a ValueError for a missing selector\")\n    except ValueError as problem:\n        print(\"\\nCorrectly raised an error for a bad selector:\")\n        print(problem)\n\n    print(\"\\nSelf-test passed.\")\n\n    # Optional secondary demo: a real fetch against books.toscrape.com,\n    # a public site built specifically for scraping practice (its HTML\n    # is meant to stay stable). May still need updating if that changes.\n    #\n    # live = scrape_product(\n    #     \"https://books.toscrape.com/catalogue/a-light-in-the-attic_1000/index.html\",\n    #     name_selector=\".product_main h1\",\n    #     price_selector=\"p.price_color\",\n    # )\n    # print(\"\\nLive fetch result:\", live)",
          "verify": "Run `python scraper.py` -- it should print `Parsed: {'name': 'Widget Pro', 'price': '$49.00'}`, then a message showing the bad-selector case was caught with a clear error instead of crashing, then `Self-test passed.`"
        }
      ],
      "goFurther": "Break it on purpose: point `scrape_product()` at a URL that returns a 404, and separately at a real page whose selectors don't match anything you expect. Both raise a clear ValueError -- that's the try/except and the None-check doing their job. Now think about a THIRD case those checks can't catch: a page that loads its price with JavaScript returns a normal 200 with real HTML, it just never contains the number your browser shows you, because requests never runs JavaScript. Nothing in this file can detect that -- it's why picking the right kind of target page matters more than the code."
    },
    {
      "number": 2,
      "title": "Detect what changed",
      "time": "25 min",
      "description": "A scrape by itself tells you nothing -- it's only useful compared against yesterday's. This file stores a snapshot and produces a list of exactly what's different, as a pure function you can test with two dictionaries you write yourself.",
      "steps": [
        {
          "instruction": "Create `tracker.py` with this code:",
          "prompt": "\"\"\"\nStep 2 of the Price & Competitor Monitor Agent.\n\nThis file compares today's scrape against yesterday's saved snapshot and\nreturns a list of what changed. The comparison itself (diff_snapshots)\nis a pure function -- give it two dictionaries, get back a list -- which\nis what makes it fully testable without ever touching the network or a\nreal file on disk.\n\"\"\"\n\nimport json\n\n\ndef load_snapshot(path):\n    \"\"\"\n    Reads a saved snapshot file from disk.\n\n    Returns an empty dict if the file doesn't exist yet -- which is\n    exactly what happens on the very first run, before there is\n    anything to compare against. Without this, the very first run of\n    the whole project would crash before it ever produced a snapshot.\n    \"\"\"\n    try:\n        with open(path, \"r\", encoding=\"utf-8\") as f:\n            return json.load(f)\n    except FileNotFoundError:\n        return {}\n\n\ndef save_snapshot(path, snapshot):\n    \"\"\"Writes today's scrape to disk so tomorrow's run has something to compare against.\"\"\"\n    with open(path, \"w\", encoding=\"utf-8\") as f:\n        json.dump(snapshot, f, indent=2)\n\n\ndef diff_snapshots(previous, current):\n    \"\"\"\n    Compares two snapshots and returns a list of change dictionaries.\n\n        previous = {\"Widget Pro\": {\"name\": \"Widget Pro\", \"price\": \"$49.00\"}}\n        current  = {\"Widget Pro\": {\"name\": \"Widget Pro\", \"price\": \"$59.00\"}}\n        diff_snapshots(previous, current)\n        # [{\"target\": \"Widget Pro\", \"type\": \"price_changed\",\n        #   \"old_price\": \"$49.00\", \"new_price\": \"$59.00\"}]\n\n    Both snapshots are dictionaries keyed by \"target\" -- the name YOU\n    chose for a product in main.py's TARGETS list, not necessarily the\n    product name scraped off the page (a competitor could rename their\n    own product between runs too, and we still want to track it as the\n    same target).\n\n    Three kinds of changes are detected: a price changing on a product\n    you're already tracking, a brand-new product appearing under a\n    target you're watching, and a product that disappeared entirely.\n    That last one is deliberately vague about WHY it disappeared --\n    delisted, or your selector stopped matching -- because this function\n    has no way to tell those apart. See the README's troubleshooting\n    section for how a human tells them apart.\n    \"\"\"\n    changes = []\n\n    for target_name, current_data in current.items():\n        if target_name not in previous:\n            changes.append({\n                \"target\": target_name,\n                \"type\": \"new_product\",\n                \"name\": current_data.get(\"name\"),\n                \"price\": current_data.get(\"price\"),\n            })\n            continue\n\n        old_price = previous[target_name].get(\"price\")\n        new_price = current_data.get(\"price\")\n        if old_price != new_price:\n            changes.append({\n                \"target\": target_name,\n                \"type\": \"price_changed\",\n                \"old_price\": old_price,\n                \"new_price\": new_price,\n            })\n\n    for target_name in previous:\n        if target_name not in current:\n            changes.append({\n                \"target\": target_name,\n                \"type\": \"product_removed\",\n                \"name\": previous[target_name].get(\"name\"),\n            })\n\n    return changes\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the diff logic works:\n    #     python tracker.py\n    previous = {\n        \"Widget Pro\": {\"name\": \"Widget Pro\", \"price\": \"$49.00\"},\n        \"Widget Mini\": {\"name\": \"Widget Mini\", \"price\": \"$19.00\"},\n    }\n    current = {\n        \"Widget Pro\": {\"name\": \"Widget Pro\", \"price\": \"$59.00\"},   # price changed\n        \"Widget Max\": {\"name\": \"Widget Max\", \"price\": \"$99.00\"},   # new product\n        # Widget Mini is gone -> product_removed\n    }\n\n    changes = diff_snapshots(previous, current)\n    print(f\"Found {len(changes)} changes:\\n\")\n    for change in changes:\n        print(\" \", change)\n\n    assert len(changes) == 3, f\"Expected 3 changes, got {len(changes)}\"\n    types_found = {c[\"type\"] for c in changes}\n    assert types_found == {\"price_changed\", \"new_product\", \"product_removed\"}, \\\n        f\"Missing a change type: {types_found}\"\n\n    # A snapshot compared against itself must never produce noise. This\n    # is exactly the bug the README's troubleshooting section warns\n    # about (\"getting an alert on every run even with no real change\")\n    # -- usually caused by comparing raw scraped text that has stray\n    # whitespace differences instead of the cleaned-up price string.\n    assert diff_snapshots(previous, previous) == [], \"Comparing a snapshot to itself found changes!\"\n\n    print(\"\\nSelf-test passed.\")",
          "verify": "Run `python tracker.py` -- it should print `Found 3 changes:` followed by the three change dictionaries (one price_changed, one new_product, one product_removed), then `Self-test passed.`"
        }
      ],
      "goFurther": "Track price history over time instead of just the latest value: append each new price to a list in the snapshot rather than overwriting it. You'd then have enough data to chart a price trend, not just spot the most recent jump."
    },
    {
      "number": 3,
      "title": "Turn changes into an alert",
      "time": "30 min",
      "description": "A list of {\"type\": \"price_changed\", ...} dictionaries means nothing to a business owner skimming their inbox. This file asks the AI to turn that structured diff into two or three plain-English sentences.",
      "steps": [
        {
          "instruction": "Create `alert.py` with this code:",
          "prompt": "\"\"\"\nStep 3 of the Price & Competitor Monitor Agent.\n\nThis file turns a list of raw changes (the kind tracker.py produces)\ninto a short, plain-English summary suitable for pasting into an email\n-- the sort of thing a human skims in five seconds, not a JSON blob.\n\"\"\"\n\nfrom sdt_ai import ask_ai\n\n# Roughly how long the AI's answer may be. A summary of a handful of\n# price changes fits comfortably in a couple of short paragraphs -- this\n# caps what one alert costs you in credits, the same way MAX_CHARACTERS\n# caps cost in the Social Post Generator project.\nMAX_TOKENS = 400\n\n\ndef build_prompt(changes):\n    \"\"\"\n    Writes the instructions we send to the AI.\n\n    We describe each change as a plain sentence rather than dumping the\n    raw dictionaries at the AI -- it writes a noticeably better summary\n    reading sentences than it does parsing structured data itself.\n    \"\"\"\n    lines = []\n    for change in changes:\n        if change[\"type\"] == \"price_changed\":\n            lines.append(\n                f\"- {change['target']}: price changed from \"\n                f\"{change['old_price']} to {change['new_price']}\"\n            )\n        elif change[\"type\"] == \"new_product\":\n            lines.append(\n                f\"- {change['target']}: new product appeared, \"\n                f\"\\\"{change['name']}\\\" at {change['price']}\"\n            )\n        elif change[\"type\"] == \"product_removed\":\n            lines.append(f\"- {change['target']}: product no longer listed on the page\")\n\n    changes_text = \"\\n\".join(lines)\n\n    return f\"\"\"A price-monitoring tool just detected the following changes on\ncompetitor pages:\n\n{changes_text}\n\nWrite a short \"what changed\" summary suitable for an email alert to a\nsmall business owner. Be specific about numbers and products -- don't\nbe vague.\n\nFormat your answer EXACTLY like this:\n\n[SUMMARY]\none sentence, the headline takeaway\n\n[DETAILS]\na few sentences of plain-English detail, referencing the actual products\nand prices listed above\n\n[END]\n\nDo not add any explanation, introduction or closing remark outside\nthose markers.\"\"\"\n\n\ndef parse_alert(reply):\n    \"\"\"\n    Turns the AI's [SUMMARY]/[DETAILS] reply into a dictionary:\n\n        {\"SUMMARY\": \"...\", \"DETAILS\": \"...\"}\n\n    Bracket markers instead of JSON, for the same reason generator.py in\n    the Social Post Generator project uses them: an AI reply that is\n    almost-but-not-quite valid JSON (a stray comma, a wrapped code\n    fence) crashes json.loads() outright. A marker line the AI gets\n    slightly wrong just fails to match and is skipped -- the function\n    degrades instead of throwing.\n\n    If the reply is malformed enough that no sections are found at all,\n    this returns an empty dict rather than raising. See summarize_changes()\n    below for how that case is handled -- a parsing hiccup should never\n    mean the alert silently vanishes.\n    \"\"\"\n    sections = {}\n    current_section = None\n    current_lines = []\n    known_sections = {\"SUMMARY\", \"DETAILS\"}\n\n    for line in reply.splitlines():\n        stripped = line.strip()\n        marker = stripped.strip(\"[]\").upper()\n        is_marker = stripped.startswith(\"[\") and stripped.endswith(\"]\")\n\n        if is_marker and marker == \"END\":\n            break\n\n        if is_marker and marker in known_sections:\n            if current_section:\n                sections[current_section] = \"\\n\".join(current_lines).strip()\n            current_section = marker\n            current_lines = []\n        elif current_section:\n            # The AI sometimes wraps its whole answer in ``` code fences.\n            # Those aren't part of the alert text, so drop them.\n            if stripped.startswith(\"```\"):\n                continue\n            current_lines.append(line)\n\n    if current_section:\n        sections[current_section] = \"\\n\".join(current_lines).strip()\n\n    return sections\n\n\ndef summarize_changes(changes, project=\"price-competitor-monitor-agent\"):\n    \"\"\"\n    The main function. Give it a list of changes from tracker.py, get\n    back a dict with SUMMARY and DETAILS text ready to drop into an\n    email or Slack message.\n\n    If nothing changed, we don't call the AI at all -- there's nothing\n    to summarize, and every call costs credits whether or not it was\n    useful.\n    \"\"\"\n    if not changes:\n        return None\n\n    prompt = build_prompt(changes)\n    reply = ask_ai(prompt, max_tokens=MAX_TOKENS, project=project)\n    parsed = parse_alert(reply)\n\n    if not parsed:\n        # The AI replied, but not with the markers we asked for. This is\n        # the AI-reliability failure mode this project has to defend\n        # against: an unparseable reply must NOT mean a missed alert --\n        # a competitor's price moving is exactly the kind of thing you\n        # can't afford to silently miss. So we fall back to emailing the\n        # AI's raw reply instead of dropping it.\n        parsed = {\"SUMMARY\": \"Competitor changes detected\", \"DETAILS\": reply.strip()}\n\n    return parsed\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the parsing works, including\n    # against a reply that ISN'T formatted the way we asked for:\n    #     python alert.py\n    good_reply = \"\"\"[SUMMARY]\nWidget Pro just got 20% more expensive.\n\n[DETAILS]\nWidget Pro rose from $49.00 to $59.00, a $10 increase. No other\nproducts changed on the pages you're tracking.\n\n[END]\"\"\"\n\n    parsed = parse_alert(good_reply)\n    print(\"Well-formed reply parsed to:\", parsed)\n    assert parsed[\"SUMMARY\"] == \"Widget Pro just got 20% more expensive.\"\n    assert \"59.00\" in parsed[\"DETAILS\"]\n\n    # A malformed reply: no brackets at all, just prose. AI replies are\n    # not guaranteed to follow formatting instructions perfectly, and a\n    # project that only ever tests the happy path breaks in production\n    # the first time this happens.\n    malformed_reply = (\n        \"Sure! Widget Pro's price went up from $49 to $59, about a 20% \"\n        \"increase. Let me know if you want more detail.\"\n    )\n    parsed_malformed = parse_alert(malformed_reply)\n    print(\"\\nMalformed reply parsed to:\", parsed_malformed)\n    assert parsed_malformed == {}, \"A malformed reply should produce no sections\"\n\n    print(\"\\nSelf-test passed.\")",
          "verify": "Run `python alert.py` -- it should print the well-formed reply's parsed SUMMARY line, then `Malformed reply parsed to: {}`, then `Self-test passed.` Notice this test never calls the real AI -- it checks your parsing logic against text you wrote yourself, the same way scraper.py's test uses a fixture instead of a live page, so it can't break just because the AI phrases something differently one day."
        }
      ],
      "goFurther": "Temporarily set MAX_TOKENS to 60 and run main.py against a real change. Watch the alert get cut off mid-sentence. That's the cost/quality tradeoff MAX_TOKENS makes concrete -- put it back to 400 once you've seen it."
    },
    {
      "number": 4,
      "title": "Wire it together and put it on a schedule",
      "time": "25 min",
      "description": "Now connect scrape -> compare -> summarize into one script you can run by hand or hand off to a scheduler.",
      "steps": [
        {
          "instruction": "Create `main.py` with this code, then edit the `TARGETS` list at the top with your own competitor page, name selector and price selector:",
          "prompt": "\"\"\"\nStep 4 of the Price & Competitor Monitor Agent -- wires the other three\nfiles together into one run: scrape -> compare -> summarize -> alert.\n\nRun it once by hand to try it:      python main.py\nRun it on a schedule (see the bottom of this file) to actually monitor\nsomething while you're not watching.\n\"\"\"\n\nfrom dotenv import load_dotenv\n\nfrom scraper import scrape_product\nfrom tracker import load_snapshot, save_snapshot, diff_snapshots\nfrom alert import summarize_changes\nfrom sdt_ai import AIError\n\nload_dotenv()\n\nSNAPSHOT_FILE = \"snapshot.json\"\n\n# Add one entry per product you want to watch. The \"target\" name is\n# yours to choose -- it's the key snapshots are tracked under between\n# runs, so keep it stable even if the scraped product name changes.\nTARGETS = [\n    {\n        \"target\": \"Competitor A - Pro Plan\",\n        \"url\": \"https://example.com/pricing\",\n        \"name_selector\": \".pro-plan .plan-name\",\n        \"price_selector\": \".pro-plan .price\",\n    },\n    # Add more targets here, one dict per product you want to track.\n]\n\n\ndef run_once():\n    \"\"\"\n    Scrapes every target, compares against the last saved snapshot, and\n    prints a summary if anything changed. Called once per schedule tick.\n    \"\"\"\n    previous = load_snapshot(SNAPSHOT_FILE)\n    current = {}\n    scrape_errors = []\n\n    for entry in TARGETS:\n        try:\n            current[entry[\"target\"]] = scrape_product(\n                entry[\"url\"], entry[\"name_selector\"], entry[\"price_selector\"]\n            )\n        except ValueError as problem:\n            # One broken selector shouldn't stop the whole run -- keep\n            # checking every other target, and just report this one.\n            scrape_errors.append(f\"{entry['target']}: {problem}\")\n\n    for problem in scrape_errors:\n        print(f\"Skipped a target: {problem}\")\n\n    changes = diff_snapshots(previous, current)\n\n    if not changes:\n        print(\"No changes detected.\")\n    else:\n        print(f\"{len(changes)} change(s) detected:\")\n        for change in changes:\n            print(\" \", change)\n\n        try:\n            alert = summarize_changes(changes)\n            print(\"\\n--- Alert ---\")\n            print(alert[\"SUMMARY\"])\n            print(alert[\"DETAILS\"])\n            # Swap these prints for send_email(...) or a Slack webhook\n            # post once you've picked how you want to be notified.\n        except AIError as problem:\n            # The AI summary failed (network hiccup, no credits left,\n            # rate limit, etc.) but the changes themselves were still\n            # detected by real scraping+diffing -- print the raw changes\n            # so a temporary AI outage never means a silently lost alert.\n            print(f\"\\nCouldn't get an AI summary ({problem})\")\n            print(\"Raw changes are listed above -- nothing was missed, just not summarized.\")\n\n    # Save today's scrape as tomorrow's \"previous\", regardless of\n    # whether anything changed. Skip this and every future run compares\n    # against the same stale snapshot forever, which is a subtler\n    # version of the \"alert every run\" bug in the troubleshooting notes.\n    save_snapshot(SNAPSHOT_FILE, current)\n\n\nif __name__ == \"__main__\":\n    run_once()\n\n    # To run this automatically instead of by hand, schedule it with\n    # cron (Mac/Linux) or Task Scheduler (Windows). A crontab line that\n    # runs it every 6 hours:\n    #\n    #     0 */6 * * * cd /path/to/this/folder && /path/to/.venv/bin/python main.py\n    #\n    # A schedule on your own laptop only fires while the laptop is on\n    # and awake -- it silently stops the moment it sleeps or shuts down.\n    # For real always-on monitoring, deploy this the same way as the\n    # WhatsApp/Gmail course guides (a free always-on host).",
          "verify": "Run `python main.py` twice in a row against a real target. The first run prints `No changes detected.` (nothing to compare against yet) and creates `snapshot.json` next to your code. Open `snapshot.json`, edit the saved price by hand, and run `python main.py` again -- it should print the detected change plus an AI-written alert under `--- Alert ---`."
        }
      ],
      "goFurther": "Add a second entry to TARGETS with a deliberately wrong selector, then run main.py. Confirm the good target still gets checked and reported -- one broken target should never take down the whole run, which is why the scraping loop catches ValueError per-target instead of letting one failure stop the script."
    },
    {
      "number": 5,
      "phaseLabel": "\ud83c\udfaf Challenge",
      "title": "Challenge: score how big a price change is",
      "time": "35 min",
      "description": "Anyone can print \"price changed\". The real test of whether you understand this tool is whether you can turn that into a number a business owner can act on without reading the details -- deciding a 2% bump isn't worth an urgent alert but a 30% jump is.",
      "steps": [
        {
          "instruction": "Add this to `tracker.py`, then finish the two functions yourself:",
          "prompt": "\"\"\"\nAdd these two functions to tracker.py. Together they turn a raw price\nchange into a number a business owner can act on at a glance, without\nreading the details -- a 2% bump and a 30% jump shouldn't look the same\nin an inbox.\n\"\"\"\n\n\ndef parse_price(price_string):\n    \"\"\"\n    Turns a price string like \"$49.00\" or \"$1,299.00\" into a float:\n    49.0, 1299.0.\n\n    TODO: strip out everything that isn't a digit or a decimal point,\n    then convert what's left to a float.\n    \"\"\"\n    raise NotImplementedError\n\n\ndef percent_change(old_price, new_price):\n    \"\"\"\n    Returns how much the price changed, as a percentage. A price going\n    up returns a positive number; a price going down returns a\n    negative one.\n\n        percent_change(\"$49.00\", \"$59.00\")     ->  20.41   (roughly)\n        percent_change(\"$1,299.00\", \"$999.00\") -> -23.09   (roughly)\n\n    TODO: use parse_price() on both arguments, then compute\n    (new - old) / old * 100.\n    \"\"\"\n    raise NotImplementedError\n",
